const SCENE_PALETTES = [
  { sky: "#CFEAE4", hill: "#8FBF9A", tree: "#4F8A5C", trunk: "#8B6B4A", water: "#2FB8AA" },
  { sky: "#D9EDE9", hill: "#A8CBA0", tree: "#5C9968", trunk: "#7A5C42", water: "#1FA093" },
  { sky: "#E3F1EC", hill: "#9FC79B", tree: "#6BA36F", trunk: "#8B6B4A", water: "#3AC4B6" },
];

function hashSeed(value) {
  const str = String(value ?? 0);
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31 + str.charCodeAt(i)) | 0;
  }
  return Math.abs(hash);
}

function SpringScene({ seed = 0, height = 120, radius = "16px 16px 0 0" }) {
  const p = SCENE_PALETTES[hashSeed(seed) % SCENE_PALETTES.length];
  return (
    <div style={{ width: "100%", height, borderRadius: radius, overflow: "hidden", position: "relative" }}>
      <svg width="100%" height="100%" viewBox="0 0 300 180" preserveAspectRatio="xMidYMid slice">
        <rect width="300" height="180" fill={p.sky} />
        <circle cx="255" cy="30" r="18" fill="#F6D77A" opacity="0.9" />
        <path d="M0 90 Q80 60 150 85 T300 75 V180 H0 Z" fill={p.hill} />
        <rect x="40" y="55" width="8" height="60" fill={p.trunk} />
        <circle cx="44" cy="50" r="20" fill={p.tree} />
        <rect x="70" y="65" width="7" height="50" fill={p.trunk} />
        <circle cx="73" cy="60" r="16" fill={p.tree} opacity="0.9" />
        <rect x="230" y="60" width="8" height="55" fill={p.trunk} />
        <circle cx="234" cy="55" r="18" fill={p.tree} />
        <path d="M0 130 Q90 105 150 128 T300 120 V180 H0 Z" fill={p.water} />
        <ellipse cx="120" cy="145" rx="60" ry="6" fill="#fff" opacity="0.18" />
        <ellipse cx="210" cy="155" rx="40" ry="4" fill="#fff" opacity="0.15" />
      </svg>
    </div>
  );
}

function SpringVisual({ spring, index, height = 120, radius = 0 }) {
  if (spring.photo) {
    return (
      <div style={{ width: "100%", height, borderRadius: radius, overflow: "hidden" }}>
        <img
          src={spring.photo}
          alt={spring.name}
          style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
        />
      </div>
    );
  }
  return <SpringScene seed={index} height={height} radius={radius} />;
}

